import java.util.*;

class Solution {
    public String removeDuplicates(String s) {
        StringBuilder sb = new StringBuilder();          // used as a stack
        for (char c : s.toCharArray()) {
            int last = sb.length() - 1;
            if (last >= 0 && sb.charAt(last) == c) sb.deleteCharAt(last); // crush the twins
            else sb.append(c);
        }
        return sb.toString();
    }
}

