function removeDuplicates(s) {
  const a = [...s]; let k = 0;
  for (let i = 0; i < a.length; i++) { if (k > 0 && a[k - 1] === a[i]) k--; else a[k++] = a[i]; }
  return a.slice(0, k).join("");
}
